import React, {useState} from 'react';
import {useNavigate} from 'react-router-dom';

function AddEmployeeForm({addAddress, addEmployee}) {

    const [email, setEmail] = useState("");
    const [employedDate, setEmployedDate] = useState("");
    const [firstName, setFirstName] = useState("");
    const [lastName, setLastName] = useState("");
    const [position, setPosition] = useState("");
    const [role, setRole] = useState("User"); // Set default value to "User"
    

    const [postCode, setPostCode] = useState("");
    const [city, setCity] = useState("");
    const [country, setCountry] = useState("");
    const [street, setStreet] = useState("");
    
    const navigate = useNavigate();

    // Handle the form submission
    const handleSubmit = async (e) => {
        // Prevent the default form submission behavior
        e.preventDefault();

        // Checking if all the fields are filled
        const requiredFields = [
            firstName, lastName, position, email, employedDate, postCode, street, city, country, role
        ];

        // Check if any of the required fields are empty
        if (requiredFields.some(field => !field)) {
            alert("Please fill in all fields");
            return;
        };

        try {
            // Create a new address
            const newAddress = {
                street: street,
                city: city,
                postCode: postCode,
                country: country
            };

            // Add new Address to the API
            const response = await addAddress(newAddress);
            console.log("Address added:", response);

            // Extract the addressId from the response
            const addressId = response.addressID; // Ensure the API returns addressId in the response
            console.log("Address ID:", addressId);

            // Check if addressId is found
            if (!addressId) {
                throw new Error("Failed to retrieve addressId from the response");
            }

            // Create a new employee
            const newEmployee = {
                firstName: firstName,
                lastName: lastName,
                email: email,
                password: "123456",
                active: true,
                employedDate: employedDate,
                position: position,
                role: role,
                address: { addressID: addressId }
            };

            // Add new Employee to the database
            const employeeResponse = await addEmployee(newEmployee);
            console.log("Employee added:", employeeResponse);

            // Clear input fields
            setEmail("");
            setEmployedDate("");
            setFirstName("");
            setLastName("");
            setPosition("");
            setRole("");
            setPostCode("");
            setCity("");
            setCountry("");
            setStreet("");

            alert("Employee successfully added!");

            // Redirect to employees page after 2 seconds
            setTimeout(() => {
                navigate('/employees');
            }, 2000);
        } catch (error) {
            console.error("Error adding employee:", error);
            alert("Failed to add employee. Please try again.");
        }

    };

    return (
        <>
        
            <h1> Add a New Employee</h1>

            <div className='formDisplayContainer'>

                <div className='imageProfileContainer'>
                    
                    <div className='imageContainer'>
                        <img src="/images/UserIcon.svg"/>
                    </div>

                    <div className='imageBtnContainer'>
                        <button className='addBtn' type="submit">Add Picture</button>
                    </div>

                </div>
            
                <form onSubmit={handleSubmit}>

                        <div className='twoFieldsHolder'>

                            <div className='formField'>
                                <label>First Name: </label>
                                <input
                                    type="text"
                                    value={firstName}
                                    onChange={(e) => setFirstName(e.target.value)}
                                    className='longInputField'
                                />
                            </div>

                            <div className='formField'>
                                <label>Last Name: </label>
                                <input
                                    type="text"
                                    value={lastName}
                                    onChange={(e) => setLastName(e.target.value)}
                                    className='longInputField'
                                />
                            </div>

                        </div>

                        <div className='twoFieldsHolder'>

                            <div className='formField'>
                                <label>Email: </label>
                                <input
                                    type="email"
                                    value={email}
                                    onChange={(e) => setEmail(e.target.value)}
                                    className='longInputField'
                                />
                            </div>

                            <div className='formField'>
                                <label>Employeed Date: </label>
                                <input
                                    type="date"
                                    value={employedDate}
                                    onChange={(e) => setEmployedDate(e.target.value)}
                                    className='dateInput'
                                />
                            </div>

                        </div>

                        <div className='twoFieldsHolder'>
                            
                            <div className='formField'>
                                <label>Position: </label>
                                <input
                                    type="text"
                                    value={position}
                                    onChange={(e) => setPosition(e.target.value)}
                                    className='longInputField'
                                />
                            </div>

                            <div className='formField'>
                                <label>Role: </label>
                                <select value={role} onChange={(e) => setRole(e.target.value)} className='formSelector'>
                                <option value="User">User</option>
                                    <option value="Administrator">Administrator</option>
                                </select>

                            </div>
                        </div>

                        <div className='formField'>
                            <label>Street: </label>
                            <input
                                type="text"
                                value={street}
                                onChange={(e) => setStreet(e.target.value)}
                                className='longInputField'
                            />
                        </div>

                        <div className='twoFieldsHolder'>

                            <div className='formField'>
                                <label>City: </label>
                                <input
                                    type="text"
                                    value={city}
                                    onChange={(e) => setCity(e.target.value)}
                                    className='shortInputField'
                                />
                            </div>
                            <div className='formField'>
                                <label>Post Code: </label>
                                <input
                                    type="text"
                                    value={postCode}
                                    onChange={(e) => setPostCode(e.target.value)}
                                    className='shortInputField'
                                />
                            </div>

                        </div>

                        <div className='formField'>
                            <label>Country: </label>
                            <input
                                type="text"
                                value={country}
                                onChange={(e) => setCountry(e.target.value)}
                                className='shortInputField'
                            />
                        </div>

                        <button className='addBtn' type="submit">Add Employee</button>

                </form>

            </div>
        
        </>
    );
}

export default AddEmployeeForm;
